  { timeout: 1_000 },
  async () => {
    const controller = new AbortController();
    const pendingTake = deferred();
    const takeStarted = deferred();
    void pendingTake.promise.catch(() => {});

    let takeCalls = 0;
    let sinkCalls = 0;
    let closeCalls = 0;
    const abortReasons = [];

    const operation = consumeBatches({
      cursor: {
        take() {
